import React, { useEffect, useState } from 'react';
import { getCabs, createCab, updateCab, deleteCab } from '../api/cab.api';
import { getDrivers } from '../api/driver.api';

const parseCurrentUser = () => {
  try { return JSON.parse(localStorage.getItem('user')); }
  catch { return null; }
};

const CabManagement = () => {
  const currentUser = parseCurrentUser();
  const isAdmin = currentUser?.role === 'admin';

  const [cabs, setCabs] = useState([]);
  const [drivers, setDrivers] = useState([]);
  const [form, setForm] = useState({ cab_number: '', model: '', driver_id: '' });
  const [editId, setEditId] = useState(null);
  const [search, setSearch] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const fetchCabs = async () => {
    try {
      const res = await getCabs();
      setCabs(res.data || []);
    } catch { setError('Failed to load cabs.'); }
  };

  const fetchDrivers = async () => {
    try {
      const res = await getDrivers();
      setDrivers(res.data || []);
    } catch {}
  };

  useEffect(() => {
    fetchCabs();
    fetchDrivers();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      const payload = {
        cab_number: form.cab_number,
        model: form.model,
        driver_id: form.driver_id || null,
        is_active: true
      };
      if (editId) {
        await updateCab(editId, payload);
      } else {
        await createCab(payload);
      }
      setForm({ cab_number: '', model: '', driver_id: '' });
      setEditId(null);
      fetchCabs();
    } catch (err) {
      setError(err.response?.data?.message || 'Operation failed.');
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (cab) => {
    setEditId(cab.id);
    setForm({ cab_number: cab.cab_number, model: cab.model, driver_id: cab.driver_id || '' });
    setError('');
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Delete this cab?')) return;
    try {
      await deleteCab(id);
      fetchCabs();
    } catch { setError('Delete failed.'); }
  };

  const handleToggleActive = async (cab) => {
    try {
      await updateCab(cab.id, {
        cab_number: cab.cab_number,
        model: cab.model,
        driver_id: cab.driver_id || null,
        is_active: !cab.is_active
      });
      fetchCabs();
    } catch { setError('Update failed.'); }
  };

  const filtered = cabs.filter((c) => {
    const t = search.toLowerCase();
    return (
      String(c.id).includes(t) ||
      c.cab_number?.toLowerCase().includes(t) ||
      c.model?.toLowerCase().includes(t) ||
      c.driver_name?.toLowerCase().includes(t)
    );
  });

  return (
    <div>
      <div className="page-title">
        <div>
          <h2>Cab Management</h2>
          <p>Organize cabs, driver assignments, and fleet availability.</p>
        </div>
      </div>

      {error && <div className="error-message" style={{ marginBottom: 16 }}>{error}</div>}

      <div className="form-card">
        <div className="card-header">
          <div>
            <h3 style={{ margin: 0, color: '#fff' }}>{editId ? 'Edit Cab' : 'Add New Cab'}</h3>
            <p style={{ color: 'var(--muted)', margin: 0 }}>
              {editId ? 'Update cab details.' : 'Register a new cab for fleet operations.'}
            </p>
          </div>
          <input
            className="filter-input"
            placeholder="Search cabs..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>

        <form onSubmit={handleSubmit} className="form-grid">
          <div className="field-group">
            <label>Cab Number</label>
            <input
              placeholder="e.g. DL01AB1234"
              value={form.cab_number}
              onChange={(e) => setForm({ ...form, cab_number: e.target.value })}
              required
            />
          </div>
          <div className="field-group">
            <label>Model</label>
            <input
              placeholder="e.g. Swift Dzire"
              value={form.model}
              onChange={(e) => setForm({ ...form, model: e.target.value })}
              required
            />
          </div>
          <div className="field-group">
            <label>Assign Driver</label>
            <select
              value={form.driver_id}
              onChange={(e) => setForm({ ...form, driver_id: e.target.value })}
            >
              <option value="">-- Unassigned --</option>
              {drivers.map(d => (
                <option key={d.id} value={d.id}>
                  {d.name || `Driver #${d.id}`} ({d.license_number})
                </option>
              ))}
            </select>
          </div>
          <div className="table-actions">
            <button type="submit" className="btn btn-primary" disabled={loading}>
              {loading ? 'Saving...' : editId ? 'Update Cab' : 'Add Cab'}
            </button>
            {editId && (
              <button type="button" className="btn btn-secondary" onClick={() => {
                setEditId(null);
                setForm({ cab_number: '', model: '', driver_id: '' });
                setError('');
              }}>
                Cancel
              </button>
            )}
          </div>
        </form>
      </div>

      <div className="table-card" style={{ marginTop: 20 }}>
        <div className="card-header">
          <div>
            <h3 style={{ margin: 0, color: '#fff' }}>Cab Inventory</h3>
            <p style={{ color: 'var(--muted)', margin: 0 }}>
              Showing {filtered.length} of {cabs.length} cabs
            </p>
          </div>
        </div>
        <div style={{ overflowX: 'auto' }}>
          <table className="data-table">
            <thead>
              <tr>
                <th>ID</th>
                <th>Cab Number</th>
                <th>Model</th>
                <th>Driver</th>
                <th>Active</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filtered.length === 0 ? (
                <tr><td colSpan={6} style={{ textAlign: 'center', color: 'var(--muted)' }}>No cabs found</td></tr>
              ) : filtered.map((c) => (
                <tr key={c.id}>
                  <td>{c.id}</td>
                  <td>{c.cab_number}</td>
                  <td>{c.model}</td>
                  <td>{c.driver_name || 'Unassigned'}</td>
                  <td>
                    <span
                      className={`status-pill ${c.is_active ? 'success' : 'danger'}`}
                      style={{ cursor: 'pointer' }}
                      onClick={() => handleToggleActive(c)}
                      title="Click to toggle"
                    >
                      {c.is_active ? 'Active' : 'Inactive'}
                    </span>
                  </td>
                  <td className="table-actions">
                    <button className="btn btn-secondary" onClick={() => handleEdit(c)}>Edit</button>
                    {isAdmin && (
                      <button className="btn btn-danger" onClick={() => handleDelete(c.id)}>Delete</button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default CabManagement;
